{
  "AP1": {
    "tx_power_dbm": 7,
    "obss_pd_dbm": -72
  },
  "AP2": {
    "tx_power_dbm": 7,
    "obss_pd_dbm": -72
  },
  "AP3": {
    "tx_power_dbm": 7,
    "obss_pd_dbm": -72
  },
  "_sr": {
    "concurrent_group": ["ap1", "ap2", "ap3"],
    "non_concurrent_aps": []
  }
}
```

